CREATE OR REPLACE FUNCTION total_loans()
    RETURNS TRIGGER
    AS $$
    BEGIN
        UPDATE loan_summary
        SET total_loan_count = (SELECT COUNT(CASE WHEN status = 'A' THEN 1 END) FROM loan WHERE loan_summary.account_id = loan.account_id) WHERE account_id = NEW.account_id; RETURN NEW;
    END;
    $$ LANGUAGE plpgsql;

stage1_sql:
CREATE OR REPLACE FUNCTION update_loan_summary()
    RETURNS TRIGGER
    AS $$
    BEGIN
        -- Only proceed if status actually changed
        IF NEW.status IS DISTINCT FROM OLD.status THEN
            -- Update the summary with count of 'A' status loans for this account
            UPDATE loan_summary
            SET 
                total_loan_count = (
                    SELECT COUNT(*) 
                    FROM loan 
                    WHERE account_id = NEW.account_id 
                    AND status = 'A'
                ),
                last_updated = CURRENT_TIMESTAMP
            WHERE account_id = NEW.account_id;

            -- If no row exists in loan_summary, insert one
            IF NOT FOUND THEN
                INSERT INTO loan_summary (
                    account_id, 
                    total_loan_count,
                    last_updated
                ) VALUES (
                    NEW.account_id,
                    (SELECT COUNT(*) FROM loan WHERE account_id = NEW.account_id AND status = 'A'),
                    CURRENT_TIMESTAMP
                );
            END IF;
        END IF;

        RETURN NEW;
    END;
    $$ LANGUAGE plpgsql;

