-- Create a more flexible validation function
CREATE OR REPLACE FUNCTION validate_account_disp()
RETURNS TRIGGER AS $$
BEGIN
    -- Allow initial inserts (when transaction hasn't completed yet)
    IF TG_OP = 'INSERT' AND NOT EXISTS (SELECT 1 FROM disp WHERE account_id = NEW.account_id) THEN
        RETURN NEW;
    END IF;

    -- For updates, enforce the constraint
    IF TG_OP = 'UPDATE' AND NOT EXISTS (SELECT 1 FROM disp WHERE account_id = NEW.account_id) THEN
        RAISE EXCEPTION 'Account % must have at least one disposition', NEW.account_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Create the constraint trigger
CREATE CONSTRAINT TRIGGER account_must_have_disp
AFTER INSERT OR UPDATE ON account
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION validate_account_disp();

-- Create the disp deletion validation function
CREATE OR REPLACE FUNCTION validate_disp_deletion()
RETURNS TRIGGER AS $$
BEGIN
    IF OLD.type = 'OWNER' AND NOT EXISTS (
        SELECT 1 FROM disp 
        WHERE account_id = OLD.account_id 
        AND type = 'OWNER' 
        AND disp_id != OLD.disp_id
    ) THEN
        RAISE EXCEPTION 'Cannot delete last OWNER disposition for account %', OLD.account_id;
    END IF;
    RETURN OLD;
END;
$$ LANGUAGE plpgsql;

-- Create trigger on disp table
CREATE TRIGGER prevent_last_owner_disp_deletion
BEFORE DELETE ON disp
FOR EACH ROW EXECUTE FUNCTION validate_disp_deletion();

