RETURNS TRIGGER AS $$
BEGIN
    -- Update dependencies when match stage changes
    IF NEW.stage <> OLD.stage THEN
        UPDATE dependency 
        SET stage1 = stage1 + (NEW.stage - OLD.stage) 
        WHERE match1 = NEW.id;

        UPDATE dependency 
        SET stage2 = stage2 + (NEW.stage - OLD.stage) 
        WHERE match2 = NEW.id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER match_stage_update_trigger
AFTER UPDATE OF stage ON match
FOR EACH ROW
EXECUTE FUNCTION update_match_stage_cascade();
```

With the trigger in place, you can then simply execute the original update statement:

```sql
