CREATE OR REPLACE FUNCTION update_team_attributes_eff_to() RETURNS TRIGGER AS $$
DECLARE
    prev_record_date TEXT;
    next_record_date TEXT;
BEGIN
    -- Find the previous record for this team
    SELECT date INTO prev_record_date
    FROM team_attributes
    WHERE team_api_id = NEW.team_api_id
    AND TO_TIMESTAMP(date, 'YYYY-MM-DD HH24:MI:SS')::DATE < TO_TIMESTAMP(NEW.date, 'YYYY-MM-DD HH24:MI:SS')::DATE
    ORDER BY TO_TIMESTAMP(date, 'YYYY-MM-DD HH24:MI:SS')::DATE DESC
    LIMIT 1;

    -- Find the next record for this team
    SELECT date INTO next_record_date
    FROM team_attributes
    WHERE team_api_id = NEW.team_api_id
    AND TO_TIMESTAMP(date, 'YYYY-MM-DD HH24:MI:SS')::DATE > TO_TIMESTAMP(NEW.date, 'YYYY-MM-DD HH24:MI:SS')::DATE
    ORDER BY TO_TIMESTAMP(date, 'YYYY-MM-DD HH24:MI:SS')::DATE ASC
    LIMIT 1;

    -- Update previous record's eff_to to be one day before new record's date
    IF prev_record_date IS NOT NULL THEN
        UPDATE team_attributes
        SET eff_to = TO_TIMESTAMP(NEW.date, 'YYYY-MM-DD HH24:MI:SS')::DATE - 1
        WHERE team_api_id = NEW.team_api_id
        AND date = prev_record_date;
    END IF;

    -- Set new record's eff_to
    IF next_record_date IS NOT NULL THEN
        NEW.eff_to := TO_TIMESTAMP(next_record_date, 'YYYY-MM-DD HH24:MI:SS')::DATE - 1;
    ELSE
        NEW.eff_to := TO_DATE('5999-12-31', 'YYYY-MM-DD');
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

