CREATE OR REPLACE FUNCTION lcp_iterate(_state text[], value text) RETURNS text[] AS $$
DECLARE
    value_arr text[];
    min_len integer;
    common_tokens text[];
    i integer;
BEGIN
    value_arr := string_to_array(value, '#');

    IF _state IS NULL THEN
        RETURN value_arr;
    END IF;

    min_len := LEAST(array_length(_state, 1), array_length(value_arr, 1));
    common_tokens := '{}';

    FOR i IN 1..min_len LOOP
        IF _state[i] = value_arr[i] THEN
            common_tokens := array_append(common_tokens, _state[i]);
        ELSE
            EXIT;
        END IF;
    END LOOP;

    RETURN common_tokens;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION lcp_final(_state text[]) RETURNS text AS $$
BEGIN
    IF _state IS NULL OR array_length(_state, 1) = 0 THEN
        RETURN '';
    END IF;

    RETURN array_to_string(_state, '#');
END;
$$ LANGUAGE plpgsql;

