    IN_REQUESTED_COLUMN VARCHAR
) RETURNS VARCHAR AS $$
DECLARE
    result_value VARCHAR;
    query TEXT;
BEGIN
    -- Build the base query
    query := 'SELECT ' || quote_ident(LOWER(IN_REQUESTED_COLUMN)) || 
